// Package selector dispatches chaos target selection to implementations registered for each selector specification type.
package selector

import (
	"context"
	"reflect"

	"github.com/pkg/errors"
	"go.uber.org/fx"

	"github.com/chaos-mesh/chaos-mesh/pkg/selector/aws"
	"github.com/chaos-mesh/chaos-mesh/pkg/selector/azure"
	"github.com/chaos-mesh/chaos-mesh/pkg/selector/container"
	"github.com/chaos-mesh/chaos-mesh/pkg/selector/gcp"
	"github.com/chaos-mesh/chaos-mesh/pkg/selector/nodevolumepath"
	"github.com/chaos-mesh/chaos-mesh/pkg/selector/physicalmachine"
	"github.com/chaos-mesh/chaos-mesh/pkg/selector/pod"
	securityselector "github.com/chaos-mesh/chaos-mesh/pkg/selector/security"
)

type Selector struct {
	selectorMap map[reflect.Type]any
}

type Target interface {
	Id() string
}

func (s *Selector) Select(ctx context.Context, spec any) ([]Target, error) {
	if spec == nil {
		return []Target{}, nil
	}

	var targets []Target
	impl, ok := s.selectorMap[reflect.TypeOf(spec)]
	if ok {
		vals := reflect.ValueOf(impl).MethodByName("Select").Call([]reflect.Value{reflect.ValueOf(ctx), reflect.ValueOf(spec)})
		ret := vals[0]

		for i := 0; i < ret.Len(); i++ {
			targets = append(targets, ret.Index(i).Interface().(Target))
		}

		err := vals[1].Interface()
		if err == nil {
			return targets, nil
		}

		return targets, err.(error)
	}

	return nil, errors.Errorf("specification type not found: %s", reflect.TypeOf(spec))
